using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Research Agent – uses MEAI tool-calling to search the web & take notes
// ---------------------------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// Build the chat client pipeline with automatic function invocation
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Instantiate the tools
var researchTools = new ResearchTools();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.SaveNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

// Prompt the user for a research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research assistant. Given a topic you will:
        1. Search the web for relevant information (make several searches with
           different queries to get broad coverage).
        2. Save important findings as notes using the note-taking tool.
        3. After gathering enough information, retrieve all your notes and
           produce a well-structured summary with key findings and references.
        Always search at least 3 times with varied queries before summarizing.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
];

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("─── Research Summary ───────────────────────────────────");
Console.WriteLine(response.Text);
Console.WriteLine("────────────────────────────────────────────────────────");

// Display collected notes
var notes = researchTools.AllNotes;
if (notes.Count > 0)
{
    Console.WriteLine($"\n📝 {notes.Count} note(s) saved during research:\n");
    for (int i = 0; i < notes.Count; i++)
    {
        Console.WriteLine($"  {i + 1}. {notes[i]}");
    }
}

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------

class ResearchTools
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "application/json" }
        }
    };

    private readonly List<string> _notes = [];

    public IReadOnlyList<string> AllNotes => _notes;

    [Description("Searches the web for the given query and returns a list of result snippets. Use this to find information about a topic.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);

            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;
            var results = new List<string>();

            // Abstract / main answer
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"[{abstractSource}] {abstractText}");

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var related))
            {
                foreach (var item in related.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text))
                        results.Add(text.GetString() ?? "");
                }
            }

            if (results.Count == 0)
                return $"No results found for \"{query}\". Try a different query.";

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Saves a research note for later reference. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all previously saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var numbered = _notes.Select((n, i) => $"{i + 1}. {n}");
        return $"Saved notes ({_notes.Count}):\n" + string.Join("\n", numbered);
    }
}

